('checkbox','Aggiornare una scelta booleana','Usare CheckboxListTile con stato e callback nullable.',"bool selected=false;","CheckboxListTile(title:const Text('Dettagli'),value:selected,onChanged:(value)=>setState(()=>selected=value??false))",'La casella conserva lo stato della pagina.'),
('switch','Usare un interruttore di preferenza','Mostrare etichetta e stato tramite SwitchListTile.',"bool enabled=false;","SwitchListTile(title:Text(enabled?'Notifiche attive':'Notifiche disattive'),value:enabled,onChanged:(value)=>setState(()=>enabled=value))",'Testo e interruttore restano sincronizzati.'),
('slider','Selezionare una quantità numerica','Separare il valore double del controllo dalla formattazione del testo.',"double value=30;","Column(children:[Slider(value:value,min:0,max:100,divisions:20,onChanged:(next)=>setState(()=>value=next)),Text('${value.toStringAsFixed(0)}%')])",'Lo slider aggiorna una percentuale.'),
('dropdown','Scegliere una voce da un menu','Conservare un valore del dominio nel DropdownButton.',"String selected='dev';","DropdownButton<String>(value:selected,items:const[DropdownMenuItem(value:'dev',child:Text('Sviluppo')),DropdownMenuItem(value:'prod',child:Text('Produzione'))],onChanged:(value){if(value!=null)setState(()=>selected=value);})",'Produzione corrisponde a prod.'),
('form','Validare un modulo con FormState','Usare un GlobalKey e validator prima di accettare il contenuto.',"final formKey=GlobalKey<FormState>();String message='';","Form(key:formKey,child:Column(children:[TextFormField(decoration:const InputDecoration(labelText:'Email'),validator:(value)=>value!=null&&value.contains('@')?null:'Inserisci una email'),ElevatedButton(onPressed:(){if(formKey.currentState!.validate())setState(()=>message='Modulo valido');},child:const Text('Conferma')),Text(message)]))",'Un campo vuoto mostra un errore e non conferma il modulo.'),
