('responsive','Scegliere il layout in base ai vincoli','Usare LayoutBuilder invece di dimensioni assolute dello schermo.',"", "LayoutBuilder(builder:(context,constraints){final wide=constraints.maxWidth>=600;return Flex(direction:wide?Axis.horizontal:Axis.vertical,children:const[Expanded(child:Card(child:Center(child:Text('Navigazione')))),Expanded(flex:2,child:Card(child:Center(child:Text('Contenuto'))))]);})",'Oltre600px i pannelli sono affiancati; sotto sono verticali.'),
('navigation','Aprire una pagina e ricevere un risultato','Attendere Navigator.push e verificare mounted prima di aggiornare lo State.',"String result='Nessuna scelta';", "Column(children:[ElevatedButton(onPressed:()async{final value=await Navigator.of(context).push<String>(MaterialPageRoute(builder:(_)=>Scaffold(appBar:AppBar(title:const Text('Dettagli')),body:Center(child:ElevatedButton(onPressed:()=>Navigator.of(context).pop('Confermato'),child:const Text('Conferma'))))));if(!mounted)return;setState(()=>result=value??'Annullato');},child:const Text('Apri dettagli')),Text(result)])",'La seconda pagina restituisce Confermato o un annullamento.'),
('dialog','Attendere la risposta di un dialogo','Usare il contesto del dialogo per chiuderlo e quello della pagina per aprirlo.',"String result='';", "Column(children:[ElevatedButton(onPressed:()async{final value=await showDialog<String>(context:context,builder:(dialogContext)=>AlertDialog(title:const Text('Conferma'),content:const Text('Procedere?'),actions:[TextButton(onPressed:()=>Navigator.of(dialogContext).pop('OK'),child:const Text('Conferma'))]));if(mounted)setState(()=>result=value??'Annullato');},child:const Text('Dialogo')),Text(result)])",'La risposta viene mostrata nella pagina senza usare un contesto sopra MaterialApp.'),
