def build_all():
    assert len(ROWS)==24,len(ROWS)
    book=Book('flutter','Flutter3.47 stable;Dart3.x incluso;API compatibili Flutter3.35+',["https://docs.flutter.dev/release/release-notes/release-notes-3.47.0","https://docs.flutter.dev/platform-integration/windows/setup","https://docs.flutter.dev/testing/overview"],"Flutter SDK stable3.47 e Dart incluso. Windows richiede Visual Studio con Desktop development with C++, non soltanto VS Code. Android richiede Android SDK/JDK e dispositivo o emulatore. macOS/iOS richiedono un Mac con Xcode e non sono verificati qui.",os=['Windows','Android'],ide=['VS Code','Android Studio'])
    basic=flutter_files("int count=0;","Column(children:[Text('$count',key:const Key('count')),ElevatedButton(key:const Key('increment'),onPressed:()=>setState(()=>count++),child:const Text('Incrementa'))])")
    procedures=[('setup','Inizializzare progetto e runner Flutter','Inizializzazione',r'flutter --version'+'\nflutter doctor -v\n.\\bootstrap.ps1\nflutter run -d windows','bootstrap.ps1 crea una cartella app nuova con runner Windows/Android ufficiali, poi copia i sorgenti recipe e risolve le sole dipendenze SDK. Non sovrascrive un progetto app già presente. Dopo lo script il terminale ènella cartella app.'),('build','Compilare il progetto Flutter per Windows','Compilazione',r'.\bootstrap.ps1'+'\nflutter analyze\nflutter build windows --debug','Prima di compilare risolvi le segnalazioni flutter doctor. La compilazione Windows richiede SDK Windows e tool C++ Visual Studio. La build Android èun comando distinto e non dimostra la compatibilità desktop.'),('debug','Usare breakpoint e hot reload in Flutter','Debug',r'.\bootstrap.ps1'+'\nflutter run -d windows','Apri la cartella app in VS Code con estensione Flutter. F5 usa il dispositivo scelto; metti un breakpoint nell’handler Incrementa. Hot reload conserva lo State, mentre hot restart riparte da zero. Non cambiare la struttura dei runner durante una sessione attiva.'),('test','Eseguire un widget test del contatore Flutter','Test',r'.\bootstrap.ps1'+'\nflutter test','Il widget test costruisce AtlasApp in un ambiente di test e interagisce con il pulsante. Non avvia un emulatore e non attesta il rendering su Android o su uno schermo fisico.'),('deploy','Preparare una build Flutter Windows Release','Distribuzione',r'.\bootstrap.ps1'+'\nflutter build windows --release','Distribuisci tutta la directory Release prodotta sotto build/windows, incluse DLL e data. Verifica su un Windows compatibile. La ricetta non crea firma o installer; Android richiede flutter build apk e la propria configurazione di firma, iOS richiede macOS/Xcode.')]
    for key,title,section,command,guide in procedures:
        data=dict(basic)
        if key=='test':data['recipe/test/widget_test.dart']="import 'package:flutter_test/flutter_test.dart';import 'package:atlas_flutter/main.dart';import 'package:flutter/material.dart';void main(){testWidgets('incrementa una volta',(tester)async{await tester.pumpWidget(const AtlasApp());expect(find.text('0'),findsOneWidget);await tester.tap(find.byKey(const Key('increment')));await tester.pump();expect(find.text('1'),findsOneWidget);});}"
        if key=='debug':data['recipe/.vscode/launch.json']=json.dumps({'version':'0.2.0','configurations':[{'name':'Flutter debug','request':'launch','type':'dart','program':'lib/main.dart'}]},indent=2);data['bootstrap.ps1']+=r'Copy-Item -LiteralPath ..\recipe\.vscode -Destination .vscode -Recurse -Force'+'\n'
        book.add(key,title,guide,data,section=section,commands=command,explanation='## Procedura\n'+guide+'\n\n## File e prerequisiti\n'+book.prerequisites+'\n\nI file lib/test originali sono sotto recipe; bootstrap li copia nel runner creato dall’SDK. Questo evita un runner nativo incompleto o dipendente dalla macchina dell’autore. I comandi vanno avviati dalla radice esportata.',expected='La procedura produce l’esito descritto quando SDK e piattaforma sono disponibili; nessun test mobile èpresunto.',tags=['flutter',key,'SDK','Windows','Android'])
    for row in ROWS:
        key,title,desc,state,body,expected,*rest=row
        imports=rest[1] if len(rest)>1 else ''
        book.add(key,title,desc,flutter_files(state,body,imports=imports),commands=r'.\bootstrap.ps1'+'\nflutter run -d windows',explanation=f'## Comportamento\n{desc}\n\n## Avvio\nEsporta tutti i file. bootstrap.ps1 crea app e copia recipe/lib e recipe/test nel progetto nativo. Il codice specifico ènello State in lib/main.dart. Per cambiare piattaforma servono i relativi toolchain; non basta modificare il nome del dispositivo.\n\n## Controllo\n{expected}\n\n## Ciclo di vita\nIl Builder sotto MaterialApp fornisce il contesto corretto a Navigator, dialoghi e ScaffoldMessenger. I controller posseduti dallo State vengono rilasciati esplicitamente dove presenti.',expected=expected,tags=['flutter',key,'widgets','state'])
    model='''class Task{final int id;final String title;final bool done;const Task(this.id,this.title,[this.done=false]);Task toggle()=>Task(id,title,!done);}
List<Task> addTask(List<Task> rows,String title){final clean=title.trim();if(clean.isEmpty)throw ArgumentError('Titolo vuoto');var id=0;for(final row in rows){if(row.id>id)id=row.id;}return List.unmodifiable([...rows,Task(id+1,clean)]);}
'''
    state="List<Task> rows=[];final controller=TextEditingController();String error='';void add(){try{final next=addTask(rows,controller.text);setState(()=>rows=next);controller.clear();setState(()=>error='');}on ArgumentError catch(e){setState(()=>error=e.message.toString());}}@override void dispose(){controller.dispose();super.dispose();}"
    body="Column(children:[TextField(controller:controller,decoration:const InputDecoration(labelText:'Nuova attività')),ElevatedButton(onPressed:add,child:const Text('Aggiungi')),Text(error),Expanded(child:ListView(children:rows.map((task)=>CheckboxListTile(key:ValueKey(task.id),title:Text(task.title),value:task.done,onChanged:(_)=>setState(()=>rows=rows.map((row)=>row.id==task.id?row.toggle():row).toList()))).toList())),Text('Completate: ${rows.where((row)=>row.done).length}')])"
    project=flutter_files(state,body,extra={'recipe/lib/model.dart':model,'recipe/test/model_test.dart':"import 'package:flutter_test/flutter_test.dart';import 'package:atlas_flutter/model.dart';void main(){test('rifiuta vuoto',()=>expect(()=>addTask([],' '),throwsArgumentError));test('ID e immutabilità',(){final old=[const Task(4,'prima')];final next=addTask(old,' seconda ');expect(old.length,1);expect(next.last.id,5);expect(next.last.title,'seconda');});test('toggle conserva origine',(){const old=Task(1,'prima');expect(old.toggle().done,true);expect(old.done,false);});}"},imports="import 'model.dart';")
    project['README.md']='# Attività Flutter\nEseguire bootstrap.ps1 da una cartella nuova. Il runner generato èin app; i sorgenti originali e i test sono in recipe. Eseguire flutter test e flutter run -d windows da app. La lista èdi sessione. Nessuna attestazione di esecuzione mobile se manca l’SDK nel report.\n'
    book.add('progetto-attivita','Progetto completo: attività Flutter con modello e test','Gestire una lista con ID stabili e completamento, separando il modello Dart dai widget e dal runner nativo generato.',project,project=True,section='Inizializzazione',commands=r'.\bootstrap.ps1'+'\nflutter analyze\nflutter test\nflutter run -d windows',explanation='## Progetto\nIl modello valida il titolo, assegna il prossimo ID e restituisce una lista nuova. La UI aggiunge righe e mostra quante sono completate; dispose rilascia il controller. Tre test unitari controllano vuoto, ID/immutabilità e toggle; il widget test verifica la costruzione della pagina.\n\n## Controllo manuale\nProva un titolo vuoto, aggiungi due attività e spuntane una: il conteggio deve essere1. Hot restart azzera lo stato, perché questo capstone non aggiunge un plugin di persistenza. I runner Windows/Android vengono generati dall’SDK locale con bootstrap riproducibile.',expected='I test forniti passano quando eseguiti con Flutter; aggiunta e checkbox aggiornano il conteggio.',tags=['flutter','project','Dart','model','test','StatefulWidget'])
    assert len(book.recipes)==30;save_book(book)

if __name__=='__main__':build_all()
